"""Explicit, reviewed language rows for meetings and profile recovery UI."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CODES='en de es fr it pt el ru sr pl sl sk cs bg ro mk hu sv nb fi da nl is'.split()
OUT={c:{} for c in CODES}
def batch(keys, rows):
 keys=keys.split('|');assert set(rows)==set(CODES)-{'ru'}
 for c in CODES:
  vals=keys if c=='ru' else rows[c].split('|')
  assert len(vals)==len(keys),(c,len(vals),len(keys))
  OUT[c].update(zip(keys,vals))
