# These aliases are exact UI synonyms; use the already reviewed translations.
for code in CODES:
 current=json.loads((ROOT/'assets/l10n'/f'{code}.json').read_text())
 for key,canonical in {'Редактировать встречу':'Изменить встречу','Сеанс завершён':'Сеанс завершён. Войдите снова.'}.items():
  OUT[code][key]=key if code=='ru' else current[canonical]
# A re-run may find our previously assembled keys in assets; they must agree.
# Serbian uses the Latn locale throughout the app. This transliteration changes
# display text only; source-language keys and persisted group values stay intact.
def serbian_latin(text):
    source = 'абвгдђежзијклљмнњопрстћуфхцчџш'
    target = ['a','b','v','g','d','đ','e','ž','z','i','j','k','l','lj','m','n','nj','o','p','r','s','t','ć','u','f','h','c','č','dž','š']
    mapping = dict(zip(source, target))
    mapping.update({a.upper(): b.title() for a,b in zip(source,target)})
    return ''.join(mapping.get(char,char) for char in text)
OUT['sr'] = {key: serbian_latin(value) for key,value in OUT['sr'].items()}
(ROOT/'tool/l10n_segments/meetings_profile.json').write_text(json.dumps(OUT,ensure_ascii=False,indent=2)+'\n')
print(len(OUT['ru']),'keys ×',len(CODES),'languages')
